using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {
class StairView:Control {public D Model;public double Yaw=-35,Pitch=30,Zoom=1;bool drag;Point anchor;public StairView(){DoubleBuffered=true;BackColor=Color.FromArgb(242,244,237);MouseDown+=(s,e)=>{drag=true;anchor=e.Location;Capture=true;};MouseUp+=(s,e)=>{drag=false;Capture=false;};MouseMove+=(s,e)=>{if(drag){Yaw+=(e.X-anchor.X)*.6;Pitch=Math.Max(2,Math.Min(88,Pitch-(e.Y-anchor.Y)*.4));anchor=e.Location;Invalidate();}};MouseWheel+=(s,e)=>{Zoom=Math.Max(.3,Math.Min(4,Zoom*(e.Delta>0?1.12:.89)));Invalidate();};MouseEnter+=(s,e)=>Focus();}
struct P {public double X,Y,Z;public P(double x,double y,double z){X=x;Y=y;Z=z;}}
class Face {public P[] Points;public double Depth;public Color Color;}
protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;if(Model==null){g.DrawString("치수를 입력하면 3D 모형을 계산합니다.",Font,Brushes.DarkGreen,20,20);return;}var boxes=J.Rows(Model,"boxes");if(boxes.Count==0)return;double a=Yaw*Math.PI/180,p=Pitch*Math.PI/180;Func<P,double[]> project=v=>new[]{v.X*Math.Cos(a)-v.Y*Math.Sin(a),(v.X*Math.Sin(a)+v.Y*Math.Cos(a))*Math.Sin(p)-v.Z*Math.Cos(p),(v.X*Math.Sin(a)+v.Y*Math.Cos(a))*Math.Cos(p)+v.Z*Math.Sin(p)};var faces=new List<Face>();var all=new List<double[]>();var labels=new List<Tuple<P,string>>();foreach(D b in boxes){double x=(double)J.Num(b,"x"),y=(double)J.Num(b,"y"),z=(double)J.Num(b,"z"),w=(double)J.Num(b,"width"),d=(double)J.Num(b,"depth"),t=(double)J.Num(b,"thickness");P[] v={new P(x,y,z),new P(x+w,y,z),new P(x+w,y+d,z),new P(x,y+d,z),new P(x,y,z+t),new P(x+w,y,z+t),new P(x+w,y+d,z+t),new P(x,y+d,z+t)};int[][] indexes={new[]{0,1,2,3},new[]{4,5,6,7},new[]{0,1,5,4},new[]{1,2,6,5},new[]{2,3,7,6},new[]{3,0,4,7}};Color[] colors={Color.FromArgb(111,76,43),Color.FromArgb(201,161,107),Color.FromArgb(161,112,67),Color.FromArgb(140,94,55),Color.FromArgb(150,104,62),Color.FromArgb(174,126,76)};for(int i=0;i<6;i++){P[] pts=indexes[i].Select(k=>v[k]).ToArray();faces.Add(new Face{Points=pts,Depth=pts.Average(pt=>project(pt)[2]),Color=J.Text(b,"kind")=="landing"?Color.FromArgb(Math.Min(255,colors[i].R+10),Math.Min(255,colors[i].G+12),colors[i].B):colors[i]});}all.AddRange(v.Select(project));labels.Add(Tuple.Create(new P(x+w/2,y+d/2,z+t+5),J.Text(b,"index")));}double minx=all.Min(v=>v[0]),maxx=all.Max(v=>v[0]),miny=all.Min(v=>v[1]),maxy=all.Max(v=>v[1]);double scale=Math.Min((Width-100)/Math.Max(1,maxx-minx),(Height-100)/Math.Max(1,maxy-miny))*Zoom;Func<P,PointF> screen=v=>{double[] q=project(v);return new PointF((float)(Width/2+(q[0]-(minx+maxx)/2)*scale),(float)(Height/2+(q[1]-(miny+maxy)/2)*scale));};using(var pen=new Pen(Color.FromArgb(92,71,47),.8f))foreach(Face f in faces.OrderBy(f=>f.Depth)){PointF[] points=f.Points.Select(screen).ToArray();using(var brush=new SolidBrush(f.Color))g.FillPolygon(brush,points);g.DrawPolygon(pen,points);}if(boxes.Count<=45)using(var font=new Font("맑은 고딕",8))foreach(var l in labels){PointF at=screen(l.Item1);g.DrawString(l.Item2,font,Brushes.Black,at);}using(var font=new Font("맑은 고딕",9))g.DrawString("3D 치수 모형 · 드래그 회전 / 휠 확대 · 번호=상승 레벨\n상부층 바닥은 마지막 레벨이며 별도 발판으로 세지 않습니다.",font,Brushes.DarkGreen,12,12);}}
class StairDesignForm:Form {Bridge bridge;D state,original,result;Func<D,bool> save;Dictionary<string,NumericUpDown> numbers=new Dictionary<string,NumericUpDown>();TextBox title=new TextBox();ComboBox shape=new ComboBox(),project=new ComboBox();CheckBox opening=new CheckBox(),autoSplit=new CheckBox();StairView view=new StairView();Label summary=new Label();TextBox issues=new TextBox();DataGridView cuts=new DataGridView(),levels=new DataGridView();bool ready;public StairDesignForm(Bridge b,D data,D record,Func<D,bool> commit){bridge=b;state=data;original=record==null?J.Row("id",Guid.NewGuid().ToString()):J.Clone(record);save=commit;Style.Form(this);Text="오름목 · 계단 3D 치수 설계 0.10";Width=1450;Height=940;MinimumSize=new Size(1180,760);D input=original.ContainsKey("inputs")?J.Obj(original["inputs"]):new D();var frame=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Padding=new Padding(12)};frame.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,325));frame.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(frame);var left=new Panel{Dock=DockStyle.Fill,AutoScroll=true};frame.Controls.Add(left,0,0);var form=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=2};form.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,165));form.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,133));left.Controls.Add(form);Action<string,Control> add=(label,control)=>{int row=form.RowCount++;form.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(0,9,0,4)},0,row);control.Dock=DockStyle.Top;control.Margin=new Padding(2,5,2,5);form.Controls.Add(control,1,row);};title.Text=J.Text(original,"name","계단 설계 "+DateTime.Today.ToString("yyyy-MM-dd"));add("설계명",title);project.DropDownStyle=ComboBoxStyle.DropDownList;project.Items.Add(new Choice("","현장 미연결"));foreach(D p in J.Rows(state,"projects"))project.Items.Add(new Choice(J.Text(p,"id"),J.Text(p,"name")));project.SelectedIndex=0;for(int i=0;i<project.Items.Count;i++)if(((Choice)project.Items[i]).Id==J.Text(original,"project"))project.SelectedIndex=i;add("연결 현장",project);shape.DropDownStyle=ComboBoxStyle.DropDownList;shape.Items.Add(new Choice("straight","일자형"));shape.Items.Add(new Choice("L","ㄱ자 + 계단참"));shape.Items.Add(new Choice("U","ㄷ자 + 계단참"));shape.SelectedIndex=0;for(int i=0;i<shape.Items.Count;i++)if(((Choice)shape.Items[i]).Id==J.Text(input,"shape"))shape.SelectedIndex=i;add("계단 형태",shape);
Action<string,string,decimal,int,decimal,decimal> number=(key,label,def,dec,min,max)=>{var n=new NumericUpDown{Minimum=min,Maximum=max,DecimalPlaces=dec,Increment=dec==0?1:.1m,ThousandsSeparator=true};decimal v=input.ContainsKey(key)?J.Num(input,key):def;n.Value=Math.Max(min,Math.Min(max,v));numbers[key]=n;add(label,n);n.ValueChanged+=(s,e)=>{if(ready){if(key=="risers"&&autoSplit.Checked)numbers["split"].Value=Math.Ceiling(n.Value/2);Calculate(false);}};};
number("height","골조 바닥간 층고 mm",2800,1,100,30000);number("lowerFinish","하부 바닥 마감 mm",0,1,0,1000);number("upperFinish","상부 바닥 마감 mm",0,1,0,1000);number("risers","전체 단높이 수 N",16,0,2,120);autoSplit.Text="반씩 자동 배분";autoSplit.Checked=!input.ContainsKey("split")||J.Num(input,"split")==Math.Ceiling(numbers["risers"].Value/2);add("계단참 구간 배분",autoSplit);number("split","첫 구간 단높이 수",8,0,1,119);number("going","디딤폭 (코끝 간) mm",260,1,20,2000);number("width","발판 재단 폭 mm",900,1,100,5000);number("thickness","발판 두께 mm",30,1,1,300);number("nosing","발판 겹침 여유 mm",30,1,0,100);number("landing","계단참 깊이 mm",1000,1,100,10000);number("gap","ㄷ자 병렬 구간 틈 mm",100,1,0,5000);number("spaceX","설치 공간 X mm",5000,1,100,100000);number("spaceY","설치 공간 Y mm",3000,1,100,100000);number("maxRise","검토 단높이 상한 mm",190,1,50,1000);number("minGoing","검토 디딤폭 하한 mm",250,1,20,1000);number("minWidth","검토 발판 폭 하한 mm",800,1,100,5000);number("maxPitch","검토 경사 상한 °",42,1,1,89);number("headroom","검토 유효높이 mm",2100,1,100,10000);number("slab","상부 슬래브 두께 mm",200,1,1,3000);opening.Text="개구부 입력 사용";opening.Checked=J.Bool(input,"opening");add("상부 슬래브 개구부",opening);number("openingX","개구부 시작 X mm",0,1,-10000,100000);number("openingY","개구부 시작 Y mm",0,1,-10000,100000);number("openingLength","개구부 X 길이 mm",4000,1,1,100000);number("openingWidth","개구부 Y 길이 mm",1000,1,1,100000);shape.SelectedIndexChanged+=(s,e)=>Calculate(false);opening.CheckedChanged+=(s,e)=>Calculate(false);autoSplit.CheckedChanged+=(s,e)=>{if(autoSplit.Checked)numbers["split"].Value=Math.Ceiling(numbers["risers"].Value/2);Calculate(false);};
var right=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};right.RowStyles.Add(new RowStyle(SizeType.Absolute,53));right.RowStyles.Add(new RowStyle(SizeType.Absolute,100));right.RowStyles.Add(new RowStyle(SizeType.Percent,62));right.RowStyles.Add(new RowStyle(SizeType.Percent,38));frame.Controls.Add(right,1,0);var tools=new FlowLayoutPanel{Dock=DockStyle.Fill};right.Controls.Add(tools,0,0);tools.Controls.Add(Style.Button("계산 / 검토",(s,e)=>Calculate(true)));tools.Controls.Add(Style.Button("단수 추천",(s,e)=>Recommend()));tools.Controls.Add(Style.Button("3D",(s,e)=>Camera(-35,30)));tools.Controls.Add(Style.Button("평면",(s,e)=>Camera(0,88)));tools.Controls.Add(Style.Button("측면",(s,e)=>Camera(0,2)));tools.Controls.Add(Style.Button("설계 저장",(s,e)=>SaveDesign()));tools.Controls.Add(Style.Button("OBJ / JSON / CSV",(s,e)=>Export()));summary.Dock=DockStyle.Fill;summary.Font=new Font(Font.FontFamily,12,FontStyle.Bold);summary.BackColor=Color.FromArgb(228,236,220);summary.Padding=new Padding(12);right.Controls.Add(summary,0,1);view.Dock=DockStyle.Fill;right.Controls.Add(view,0,2);var tabs=new TabControl{Dock=DockStyle.Fill};right.Controls.Add(tabs,0,3);foreach(var pair in new[]{Tuple.Create("발판 / 계단참 재단표",cuts),Tuple.Create("누적 레벨 · 단높이",levels)}){var tab=new TabPage(pair.Item1);pair.Item2.Dock=DockStyle.Fill;pair.Item2.ReadOnly=true;pair.Item2.AllowUserToAddRows=false;pair.Item2.RowHeadersVisible=false;pair.Item2.ColumnHeadersHeight=34;pair.Item2.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;pair.Item2.BackgroundColor=Color.White;tab.Controls.Add(pair.Item2);tabs.TabPages.Add(tab);}var warningTab=new TabPage("검토 결과 · 적용 한계");issues.Multiline=true;issues.ReadOnly=true;issues.ScrollBars=ScrollBars.Vertical;issues.Dock=DockStyle.Fill;issues.BackColor=Color.White;warningTab.Controls.Add(issues);tabs.TabPages.Add(warningTab);ready=true;Calculate(false);}
D ReadInput(){D p=new D();foreach(var n in numbers)p[n.Key]=n.Value.Value;p["shape"]=((Choice)shape.SelectedItem).Id;p["opening"]=opening.Checked;return p;}
void Camera(double yaw,double pitch){view.Yaw=yaw;view.Pitch=pitch;view.Zoom=1;view.Invalidate();}
bool Calculate(bool alert){if(!ready)return false;try{result=bridge.Call("stairs",ReadInput());view.Model=result;view.Invalidate();string clearance=result["minClearance"]==null?(opening.Checked?"개구부 안 / 다른 장애물 미검사":"미확인"):J.Num(result,"minClearance").ToString("N1")+"mm";summary.Text="단높이 "+J.Num(result,"rise").ToString("N3")+"mm   · 디딤폭 "+J.Num(result,"going")+"mm   · 구간 경사 "+J.Num(result,"pitch").ToString("N2")+"°\r\n발판 "+J.Num(result,"treadCount")+"개 / 계단참 "+J.Num(result,"landingCount")+"개 · 목재 범위 "+J.Num(result,"footprintX")+" × "+J.Num(result,"footprintY")+"mm\r\n상부 높이 "+clearance+" · 구조·법규·실측 승인 아님";var checks=J.Rows(result,"issues");summary.ForeColor=checks.Any(x=>J.Text(x,"level")=="error")?Color.Firebrick:Color.FromArgb(92,73,24);cuts.Columns.Clear();foreach(string h in new[]{"부재","레벨","X mm","Y mm","상면 Z mm","재단 X mm","재단 Y mm","두께 mm"})cuts.Columns.Add(h,h);foreach(D box in J.Rows(result,"boxes"))cuts.Rows.Add(J.Text(box,"label"),J.Num(box,"index"),J.Num(box,"x"),J.Num(box,"y"),J.Num(box,"top"),J.Num(box,"width"),J.Num(box,"depth"),J.Num(box,"thickness"));levels.Columns.Clear();foreach(string h in new[]{"단높이 번호","누적 마감 레벨 mm","해당 단높이 mm","구분"})levels.Columns.Add(h,h);foreach(D level in J.Rows(result,"levels"))levels.Rows.Add(J.Num(level,"riser"),J.Num(level,"level"),J.Num(level,"rise"),J.Text(level,"kind"));issues.Text=String.Join("\r\n",checks.Select(x=>"["+J.Text(x,"level")+"] "+J.Text(x,"text")))+"\r\n\r\n입력 기본값은 예시 검토값이며 공통 법정 기준이 아닙니다. 발판 폭과 실제 난간 사이 유효폭은 다를 수 있습니다.\r\n단수 N은 전체 상승 횟수입니다. 일자형 발판은 N-1개, 계단참 1개가 있으면 일반 발판은 N-2개입니다.\r\n겹침 여유는 발판 재단 깊이에 가산합니다. 측판 홈·받침·앵커·난간·구조 하중·도장 공차는 계산하지 않습니다.\r\n상부 간섭은 직사각형 개구부 밖의 발판/계단참 전체 투영범위를 보수적으로 검사합니다. 천장 보·덕트·사람 동선 모델은 포함하지 않습니다.\r\n마감 레벨은 하부 완성 바닥 0을 기준으로 하며, 재단표의 좌표는 전체 목재 범위 최소 X/Y를 원점으로 정규화했습니다.\r\n누적 레벨 표는 0.1mm 반올림으로 표기합니다. 구간 대각선은 끝점 거리이며 실제 측판 절단선이 아닙니다.\r\n참고 법령: 건축물의 피난·방화구조 등의 기준에 관한 규칙 제15조(2026-10-06 시행). 적용 대상과 용도별 조건을 별도 확인하세요.";if(checks.Count==0)issues.Text="입력 검토값에 대한 수치 초과는 없습니다. 구조·법규·상부 장애물까지 승인된 결과가 아닙니다.\r\n"+issues.Text;return true;}catch(Exception e){result=null;view.Model=null;view.Invalidate();summary.Text="계산할 수 없습니다: "+e.Message;if(alert)MessageBox.Show(e.Message,"설계 입력 확인");return false;}}
void SaveDesign(){if(!Calculate(true))return;if(title.Text.Trim()==""){MessageBox.Show("설계명을 입력하세요.");return;}D d=J.Clone(original);d["name"]=title.Text.Trim();d["project"]=((Choice)project.SelectedItem).Id;d["inputs"]=ReadInput();d["updatedAt"]=DateTime.Now.ToString("o");d["reviewStatus"]=J.Bool(result,"geometryChecksPassed")?"치수 검토 / 승인 전":"치수 오류 검토 필요";if(save(d)){MessageBox.Show("설계를 저장했습니다. 시공 승인 자료는 아닙니다.");}}
void Recommend(){try{D r=bridge.Call("stairsRecommend",ReadInput());var rows=J.Rows(r,"candidates");if(rows.Count==0){MessageBox.Show("현재 디딤폭·설치 공간·검토값을 만족하는 후보가 없습니다.");return;}using(var f=new Form{Text="단수 후보 · 실측/구조 승인 아님",Width=800,Height=450}){Style.Form(f);var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};foreach(string h in new[]{"단높이 수","단높이 mm","경사 °","목재 X mm","목재 Y mm"})g.Columns.Add(h,h);foreach(D row in rows){int n=g.Rows.Add(J.Num(row,"risers"),J.Num(row,"rise"),J.Num(row,"pitch"),J.Num(row,"footprintX"),J.Num(row,"footprintY"));g.Rows[n].Tag=row;}g.DoubleClick+=(s,e)=>{if(g.CurrentRow==null)return;D chosen=(D)g.CurrentRow.Tag;numbers["risers"].Value=J.Num(chosen,"risers");numbers["split"].Value=J.Num(chosen,"split");Calculate(false);f.Close();};f.Controls.Add(g);f.ShowDialog(this);}}catch(Exception e){MessageBox.Show(e.Message);}}
void Export(){try{bridge.Call("backup");}catch(Exception ex){MessageBox.Show(ex.Message);return;}if(!Calculate(true))return;using(var f=new SaveFileDialog{Filter="3D OBJ (mm)|*.obj|설계 JSON|*.json|재단표 CSV|*.csv",FileName="오름목-계단설계"})if(f.ShowDialog()==DialogResult.OK){string ext=Path.GetExtension(f.FileName).ToLower();if(ext==".json")File.WriteAllText(f.FileName,J.S.Serialize(J.Row("name",title.Text,"result",result)),System.Text.Encoding.UTF8);else if(ext==".obj")File.WriteAllText(f.FileName,ToObj(result),System.Text.Encoding.UTF8);else{var rows=new List<string>{"부재,레벨,X_mm,Y_mm,상면Z_mm,재단X_mm,재단Y_mm,두께_mm"};foreach(D box in J.Rows(result,"boxes"))rows.Add("\""+J.Text(box,"label").Replace("\"","\"\"")+"\","+String.Join(",",new[]{"index","x","y","top","width","depth","thickness"}.Select(k=>J.Num(box,k).ToString(System.Globalization.CultureInfo.InvariantCulture))));rows.Add("\"검토용 / 구조·시공 승인 아님\"");File.WriteAllLines(f.FileName,rows,new System.Text.UTF8Encoding(true));}}}
public static string ToObj(D model){var s=new System.Text.StringBuilder("# OreumMok parametric stair model\n# Units: millimeters. Review only; not structural approval.\n");int start=1;foreach(D box in J.Rows(model,"boxes")){double x=(double)J.Num(box,"x"),y=(double)J.Num(box,"y"),z=(double)J.Num(box,"z"),w=(double)J.Num(box,"width"),d=(double)J.Num(box,"depth"),t=(double)J.Num(box,"thickness");double[][] v={new[]{x,y,z},new[]{x+w,y,z},new[]{x+w,y+d,z},new[]{x,y+d,z},new[]{x,y,z+t},new[]{x+w,y,z+t},new[]{x+w,y+d,z+t},new[]{x,y+d,z+t}};s.AppendLine("o part_"+start);foreach(var point in v)s.AppendLine("v "+String.Join(" ",point.Select(n=>n.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture))));foreach(int[] face in new[]{new[]{0,3,2,1},new[]{4,5,6,7},new[]{0,1,5,4},new[]{1,2,6,5},new[]{2,3,7,6},new[]{3,0,4,7}})s.AppendLine("f "+String.Join(" ",face.Select(n=>(n+start).ToString())));start+=8;}return s.ToString();}
}
partial class MainForm {void DesignWorkspace(){var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,55));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(layout);var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(bar,0,0);var designGrid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White,ColumnHeadersHeight=35};foreach(string label in new[]{"설계명","현장","형태","단높이 수","검토 상태"})designGrid.Columns.Add(label,label);foreach(D d in J.Rows(state,"designs")){D p=J.Obj(d.ContainsKey("inputs")?d["inputs"]:null);int n=designGrid.Rows.Add(J.Text(d,"name"),RecordName("projects",J.Text(d,"project")),J.Text(p,"shape"),J.Num(p,"risers"),J.Text(d,"reviewStatus"));designGrid.Rows[n].Tag=d;}layout.Controls.Add(designGrid,0,1);Action<D> open=d=>{using(var f=new StairDesignForm(b,state,d,row=>Store("designs",row)))f.ShowDialog(this);};bar.Controls.Add(Style.Button("＋ 계단 3D 설계",(s,e)=>open(null)));bar.Controls.Add(Style.Button("설계 열기",(s,e)=>{if(designGrid.CurrentRow!=null)open((D)designGrid.CurrentRow.Tag);}));bar.Controls.Add(Style.Button("새로고침",(s,e)=>{LoadState();ShowPage("design");}));designGrid.DoubleClick+=(s,e)=>{if(designGrid.CurrentRow!=null)open((D)designGrid.CurrentRow.Tag);};}}
}
